from pathlib import Path
import re,json,shutil
root=Path(__file__).resolve().parents[1]
shutil.copy2(root.parents[1]/'PhoneApp/Assets.xcassets/AppIcon.appiconset/AppIcon-dark.png',root/'creative/brand-icon.png')
p=root/'creative/exports.html';p.write_text(p.read_text().replace("../../../PhoneApp/Assets.xcassets/AppIcon.appiconset/AppIcon-dark.png","brand-icon.png"))
meta={}
for locale in ['zh-Hans','en-US']:
 s=(root/f'metadata-{locale}.md').read_text();blocks=re.findall(r'```text\n(.*?)\n```',s,re.S)
 fields=['name','subtitle','promotionalText','description','keywords']
 meta[locale]={k:{'value':v,'characters':len(v),'utf8Bytes':len(v.encode())} for k,v in zip(fields,blocks)}
(root/'metadata.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n')
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WatchMusic 1.0.0 · 上架素材</title><style>
*{box-sizing:border-box}body{margin:0;font:16px/1.6 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;background:#0d1422;color:#e9f0fc}main{max-width:1440px;margin:auto;padding:56px 40px}header{display:flex;gap:18px;align-items:center}header img{width:68px;border-radius:17px}h1{font-size:34px;margin:0;letter-spacing:-1px}h2{font-size:24px;margin-top:60px}p{color:#a5b6d0}a{color:#85bbff;text-underline-offset:4px}nav{display:flex;flex-wrap:wrap;gap:24px;margin:30px 0}figure{margin:0}figcaption{font-size:13px;color:#b5c7df;margin-top:12px}.wide{display:grid;grid-template-columns:1.5fr 1fr;gap:24px;align-items:start}img{width:100%;display:block;border-radius:16px}.phones,.watches{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}.watches{max-width:1050px}.watches img{border-radius:0}.panel{padding:25px;border:1px solid #30415b;background:#131f32;border-radius:20px;margin:20px 0}.fields{display:grid;grid-template-columns:1fr 1fr;gap:25px}.field{margin-bottom:23px}.label{display:flex;align-items:center;justify-content:space-between;font-size:13px;color:#97b4d8;margin-bottom:9px}textarea,input{display:block;width:100%;background:#0b1423;border:1px solid #3b4c65;color:#ecf4ff;font:inherit;font-size:14px;line-height:1.65;border-radius:10px;padding:13px}textarea{min-height:95px;resize:vertical}textarea.description{min-height:350px}button{background:#263e5d;border:0;color:#b9d8ff;padding:6px 12px;border-radius:9px;cursor:pointer}.pill{font-size:12px;padding:6px 12px;color:#b8d6ff;background:#19324f;border-radius:30px;display:inline-block}.note{font-size:13px;color:#97aac5}footer{margin-top:50px;border-top:1px solid #2b3a52;padding-top:25px}@media(max-width:800px){main{padding:30px 20px}.wide,.fields{grid-template-columns:1fr}.phones,.watches{grid-template-columns:repeat(2,1fr)}h1{font-size:26px}}
</style></head><body><main><header><img src="creative/brand-icon.png" alt="WatchMusic"><div><h1>WatchMusic · 上架素材</h1><p style="margin:0">随身音乐 · 1.0.0 · 2026.10.29</p></div></header><nav><a href="#creative">标题与搜索图</a><a href="#phone">手机截图</a><a href="#watch">手表截图</a><a href="#copy">可复制文案</a><a href="submission-guide.md">上传说明</a><a href="keyword-bank.md">备用关键词库</a></nav><p>每个平台只提供一种标准截图尺寸；图片点击可打开原图。此页为本地素材预览，网页部署请使用独立的四个 HTML 压缩包。</p>
<h2 id="creative">标题与搜索结果</h2><p>蓝色品牌 · 腕间离线音乐 · 按展示位分别构图</p>'''
for lang,title in [('zh-Hans','简体中文'),('en-US','English')]:
 html+=f'<h3>{title}</h3><div class="wide"><figure><a href="creative/header-{lang}.png"><img src="creative/header-{lang}.png" alt="{title}标题素材"></a><figcaption>标题 · 3840 × 1646</figcaption></figure><figure><a href="creative/search-{lang}.png"><img src="creative/search-{lang}.png" alt="{title}搜索结果素材"></a><figcaption>搜索结果 · 1920 × 1280</figcaption></figure></div>'
html+='<h2 id="phone">iPhone · 1320 × 2868</h2><p>按 01—04 顺序上传到 iPhone 最大显示屏组。英文版只翻译营销短文案，真实应用界面仍是简体中文。</p>'
for lang,title in [('zh-Hans','简体中文'),('en-US','English')]:
 html+=f'<h3>{title}</h3><div class="phones">'
 for i,name in enumerate(['离线聆听','目录整理','长按多选','目录歌曲'],1):
  url=f'screenshots/{lang}/iphone/0{i}.png';html+=f'<figure><a href="{url}"><img src="{url}" alt="{name}"></a><figcaption>0{i} · {name}</figcaption></figure>'
 html+='</div>'
html+='<h2 id="watch">Apple Watch · 422 × 514</h2><p>四张原生界面，无设备外框；两种商店语言复用同一组原图。</p><div class="watches">'
for i,name in enumerate(['独立播放器','音乐库','歌曲列表','传输进度'],1):
 url=f'screenshots/watch/0{i}.png';html+=f'<figure><a href="{url}"><img src="{url}" alt="{name}"></a><figcaption>0{i} · {name}</figcaption></figure>'
html+='</div><p class="note">演示歌曲与封面为本次原创。传输截图使用项目已有预览状态，数字不代表真实测速。<a href="capture-notes.md">查看截图来源</a></p><h2 id="copy">商店文案 · 直接复制</h2><p>关键词已按较严格的 100 UTF-8 bytes 控制。相关扩展词留在备用词库，避免超过上限或重复堆叠。</p><div class="fields" id="fields"></div><footer><a href="metadata-zh-Hans.md">完整中文信息与审核备注</a> · <a href="metadata-en-US.md">Complete English listing</a> · <a href="submission-guide.md">上传说明</a><p class="note">准备素材不代表已经部署网站、提交 App Store 或获得审核通过。</p></footer></main><script>const metadata=__META__;const labels={name:"名称 / Name",subtitle:"副标题 / Subtitle",promotionalText:"推广文本 / Promotional text",description:"描述 / Description",keywords:"关键词 / Keywords"};for(const [locale,fields] of Object.entries(metadata)){const panel=document.createElement("section");panel.className="panel";const h=document.createElement("h3");h.textContent=locale;panel.append(h);for(const [key,data] of Object.entries(fields)){const field=document.createElement("div");field.className="field";const label=document.createElement("div");label.className="label";const span=document.createElement("span");span.textContent=labels[key]+" · "+(key==="keywords"?data.utf8Bytes+" bytes":data.characters+" chars");const button=document.createElement("button");button.textContent="复制";const value=document.createElement("textarea");value.value=data.value;value.readOnly=true;value.className=key;value.setAttribute("aria-label",labels[key]+" "+locale);button.addEventListener("click",async()=>{try{await navigator.clipboard.writeText(data.value);button.textContent="已复制"}catch{value.focus();value.select();button.textContent="已选中，请复制"}});label.append(span,button);field.append(label,value);panel.append(field)}document.getElementById("fields").append(panel)}</script></body></html>'''
(root/'index.html').write_text(html.replace('__META__',json.dumps(meta,ensure_ascii=False)))
